{
  "name": "exposure-audit",
  "owner": {
    "name": "Charlie Hills",
    "url": "https://charliehills.substack.com"
  },
  "plugins": [
    {
      "name": "exposure-audit",
      "source": ".",
      "description": "A Claude skill that audits your own setup and tells you which API keys you have left lying around. Scopes your surface first, then runs the twenty classic vibe-coding vulnerability checks against it. Catches the three things published lists miss: live keys inside cloud-synced folders, unrevoked keys from products you shut down, and abandoned deployments still holding environment variables. Never prints a secret value, never fixes anything, and reports NOT RUN instead of guessing.",
      "version": "1.0.1",
      "metadata": {
        "categories": [
          "security"
        ],
        "tags": [
          "security audit",
          "api keys",
          "secret scanning",
          "git history",
          "vibe coding",
          "credentials"
        ]
      }
    }
  ]
}
